457 :     private void fixTypeNode(Node typeNode) {
458 :       if (typeNode.isString()) {
459 :         String name = typeNode.getString();
460 :         int endIndex = name.indexOf('.');
461 :         if (endIndex == -1) {
462 :           endIndex = name.length();
463 :         }
464 :         String baseName = name.substring(0, endIndex);
465 :         Var aliasVar = aliases.get(baseName);
466 :         if (aliasVar != null) {
467 :           Node aliasedNode = aliasVar.getInitialValue();
468 :           aliasUsages.add(new AliasedTypeNode(typeNode, aliasedNode.getQualifiedName() + name.substring(endIndex)));
