"295 :     private void findAliases(NodeTraversal t) {
296 :       Scope scope = t.getScope();
297 :       for (Var v : scope.getVarIterable()) {
298 :         Node n = v.getNode();
299 :         int type = n.getType();
300 :         Node parent = n.getParent();
301 :         if (parent.isVar() &&
302 :             n.hasChildren() && n.getFirstChild().isQualifiedName()) {
303 :           String name = n.getString();
304 :           Var aliasVar = scope.getVar(name);
305 :           aliases.put(name, aliasVar);
306 : 
307 :           String qualifiedName =
308 :               aliasVar.getInitialValue().getQualifiedName();
309 :           transformation.addAlias(name, qualifiedName);
310 : 
311 :           int rootIndex = qualifiedName.indexOf(".");
312 :           if (rootIndex != -1) {
313 :             String qNameRoot = qualifiedName.substring(0, rootIndex);
314 :             if (!aliases.containsKey(qNameRoot)) {
315 :               forbiddenLocals.add(qNameRoot);
316 :             }
317 :           }
318 :         } else if (v.isBleedingFunction()) {
319 :           // Bleeding functions already get a BAD_PARAMETERS error, so just
320 :           // do nothing.
321 :         } else if (parent.getType() == Token.LP) {
322 :           // Parameters of the scope function also get a BAD_PARAMETERS
323 :           // error.
324 :         } else {
325 :           // TODO(robbyw): Support using locals for private variables.
326 :           report(t, n, GOOG_SCOPE_NON_ALIAS_LOCAL, n.getString());
327 :         }
328 :       }
329 :     }"

