424 :           report(t, n, GOOG_SCOPE_USES_RETURN);
425 :         } else if (type == Token.THIS) {
426 :           report(t, n, GOOG_SCOPE_REFERENCES_THIS);
427 :         } else if (type == Token.THROW) {
428 :           report(t, n, GOOG_SCOPE_USES_THROW);
429 :         }
